#include <string>
#include <sstream>

using namespace std;

class Solution {
public:
    string truncateSentence(string s, int k) {
        stringstream ss(s);
        string word, res;
        while (k-- && ss >> word) {
            if (!res.empty()) res += " ";
            res += word;
        }
        return res;
    }
};
